function heading(label,title,sub,actions=''){return `<div class="heading"><div><span class="eyebrow">${label}</span><h1>${title}</h1><p class="sub">${sub}</p></div><div class="actions">${actions}</div></div>`}function pill(v){let c=/confirm|valid|publi|termin|reçu|payé/i.test(v)?'green':/annul|refus|retard/i.test(v)?'red':/cours|attente|prévu|réserv/i.test(v)?'orange':'';return `<span class="pill ${c}">${esc(v||'À traiter')}</span>`}function empty(title,desc){return `<div class="empty"><strong>${title}</strong>${desc}</div>`}function actions(kind){return `<button class="btn primary" data-add="${kind}">+ Ajouter</button>`}function zname(z){return db.zones.find(x=>x.id===z)?.name||'Non attribuée'}function occupied(z){return sum(db.exhibitors.filter(x=>x.zone===z&&x.status!=='Annulé'),x=>x.tables||1)}function capacityRows(){return db.zones.map(z=>{let used=occupied(z.id);return `<div class="zone-row"><span class="name">${esc(z.name)}</span><span class="bar"><i style="width:${Math.min(100,used/Math.max(1,z.capacity)*100)}%;background:${esc(z.color)}"></i></span><small>${used} / ${z.capacity}</small></div>`}).join('')}function suggestion(e){let prefs=[e.choice1,e.choice2,e.choice3].filter(Boolean);let options=prefs.map((z,i)=>({z,rank:i+1,score:db.settings.score[i],free:(db.zones.find(x=>x.id===z)?.capacity||0)-occupied(z)+(e.zone===z?Number(e.tables||1):0)})).filter(x=>x.free>=Number(e.tables||1));return options.sort((a,b)=>b.score-a.score)[0]||null}
