 +`<section class="dashboard-section overview-attendance" aria-label="Exposants et tables"><div class="stat overview-exhibitors"><span class="eyebrow">PARTICIPATION</span><span class="k">Remplissage tables</span><strong>${tableCount}<span> / ${activeTableTotal()}</span></strong><small>tables attribuées</small></div><div class="stat overview-exhibitors"><span class="eyebrow">PARTICIPATION</span><span class="k">Nombre d’exposants</span><strong>${exhibitors.length}</strong><small>exposants inscrits</small></div><div class="stat overview-exhibitors"><span class="eyebrow">PARTENAIRES</span><span class="k">Partenaires engagés</span><strong>${partnerCount}</strong><small>Hors refusés, à contacter et en discussion</small></div></section>`
