function coloredTag(value){let v=String(value||'Autre'),key=/basket/i.test(v)?'basket':/soccer/i.test(v)?'soccer':/sports? us/i.test(v)?'sports':/tcg/i.test(v)?'tcg':'other';return `<span class="community-tag ${key}">${esc(v)}</span>`}
function communityEmoji(v){let c=norm(v);return /basket|nba/.test(c)?'🏀':/soccer|foot(?!ball americain)/.test(c)?'⚽':/nfl|football americain|sport us/.test(c)?'🏈':/tennis/.test(c)?'🎾':/formule|formula|f1/.test(c)?'🏎️':/baseball|mlb/.test(c)?'⚾':/hockey|nhl/.test(c)?'🏒':/tcg|pokemon|one piece|magic/.test(c)?'🃏':'🎴'}
