function partnerAmount(x){return partnerRevenue(x,db.settings)}
function syncExhibitorPricing(form,normalize=false){if(form?.dataset.kind!=='exhibitors'||form._quoteState?.activeSpaceQuoteId)return;const tables=form.elements.tables,amount=form.elements.amount,type=form.elements.vendorType.value;if(!tables.value||Number(tables.value)<1){if(!normalize)return;tables.value='1'}const total=exhibitorAmount(type,tables.value,db.settings);if(total!==null)amount.value=String(total);const hint=form.querySelector('#exhibitorPriceHint');if(hint)hint.textContent=total===null?'Choisis un type de vendeur pour calculer le montant.':type==='Partenaire'?`Forfait partenaire : ${euro(total)} · montant modifiable.`:`Tarif Le Salon : ${euro(exhibitorAmount(type,1,db.settings))} × ${tableCount(tables.value)} table(s) · montant modifiable.`}
function exhibitorKPIs(){const active=db.exhibitors.filter(x=>x.status!=='Annulé');const zoneCards=db.zones.map(z=>{const items=active.filter(x=>normalizeCommunity(x.community)===normalizeCommunity(z.name)),tables=sum(items,x=>tableCount(x.tables)),amount=sum(items,x=>exhibitorRevenue(x,db.settings)),pros=items.filter(x=>vendorFromRate(x.vendorType)==='Pro').length,individuals=items.filter(x=>vendorFromRate(x.vendorType)==='Collectionneur').length;return `<article class="stat exhibitor-zone-kpi" style="--zone-color:${/^#[0-9a-f]{6}$/i.test(z.color)?z.color:'#1303e3'}"><span class="k">${esc(z.name)}</span><strong>${tables}<small> tables</small></strong><span class="money-positive">${euro(amount)}</span><small class="exhibitor-vendor-counts"><span>${pros} pro${pros>1?'s':''}</span><span>${individuals} particulier${individuals>1?'s':''}</span></small></article>`}).join('');const groups=[['Pro','#1303e3',x=>x.vendorType==='Pro'],['Particulier','#FE4F14',x=>x.vendorType==='Collectionneur'],['Artiste','#11B8C5',x=>x.vendorType==='Artiste'],['Partenaire','#17a36d',x=>x.vendorType==='Partenaire'],['Autre','#8e93a5',x=>!['Pro','Collectionneur','Artiste','Partenaire'].includes(x.vendorType)]],total=active.length;let offset=0;const segments=groups.map(([name,color,match])=>{const count=active.filter(match).length,start=offset;offset+=total?count/total*100:0;return {name,color,count,start,end:offset}});const gradient=total?segments.filter(x=>x.count).map(x=>`${x.color} ${x.start}% ${x.end}%`).join(','):'var(--line) 0% 100%';return participationSummary('exhibitors')+`<div class="exhibitor-kpis"><section class="exhibitor-zone-grid" aria-label="Tables et recettes par communauté">${zoneCards}</section><section class="panel exhibitor-types"><div><span class="eyebrow">RÉPARTITION</span><h2>Types de vendeurs</h2></div><div class="exhibitor-types-body"><div class="vendor-donut" style="background:conic-gradient(${gradient})" role="img" aria-label="${esc(segments.map(x=>x.name+' : '+x.count).join(', '))}"><span><strong>${total}</strong><small>exposants</small></span></div><div class="vendor-legend">${segments.filter(x=>x.count||['Pro','Particulier','Artiste'].includes(x.name)).map(x=>`<div><i style="background:${x.color}"></i><span>${x.name}</span><strong>${x.count}</strong></div>`).join('')}</div></div></section></div>`}
function exhibitors(){if(exhibitorTab==='partners')return exhibitorPartners();if(exhibitorTab==='plan')return exhibitorPlan();let cols=[['last','Nom'],['first','Prénom'],['company','Société'],['community','Communauté'],['vendorType','Type'],['amount','Montant'],['tables','Tables'],['zone','Zone'],['status','Statut'],['note','Commentaires']];let rows=db.exhibitors.filter(x=>JSON.stringify(x).toLowerCase().includes(query.toLowerCase())&&cols.every(([k])=>!columnFilters[k]||String(x[k]??'')===columnFilters[k]));let bulk=selectedExhibitors.size?`<div class="bulk-bar"><strong>${selectedExhibitors.size} sélectionné(s)</strong><button class="btn small dark" data-action="bulk-edit">Modifier</button><button class="btn small danger" data-action="bulk-delete">Supprimer</button><button class="btn small" data-action="bulk-clear">Désélectionner</button></div>`:'';return heading('INSCRIPTIONS','Exposants','Import, attribution et modification groupée.',`<button class="btn" data-action="import-csv">↑ Import CSV</button>${actions('exhibitors')}`)+`<div class="tabs"><button class="active" data-exhibitor-tab="exhibitors">Exposants</button><button data-exhibitor-tab="partners">Partenaires du salon</button><button data-exhibitor-tab="plan">Plan</button></div>`+exhibitorKPIs()+searchBar()+bulk+`<div class="panel table-wrap">${rows.length?`<table class="data"><thead><tr><th><input type="checkbox" id="selectAll" aria-label="Tout sélectionner"></th>${cols.map(([k,l])=>filterHead(db.exhibitors,k,l)).join('')}<th>Action</th></tr></thead><tbody>${rows.map(e=>{let [first,last]=nameParts(e),sug=suggestion(e);return `<tr tabindex="0" data-row-edit="exhibitors:${esc(e.id)}"><td><input type="checkbox" data-select-exhibitor="${esc(e.id)}" ${selectedExhibitors.has(e.id)?'checked':''} aria-label="Sélectionner"></td><td><strong>${esc(last)}</strong></td><td>${esc(first)}</td><td>${esc(e.company||'—')}</td><td>${coloredTag(e.community)}${needsCommunityReview(e)?`<div class="community-warning" role="status">⚠ Choix 1 : ${esc(zname(e.choice1))}<button type="button" class="linkbtn" data-approve-community="${esc(e.id)}">Valider</button></div>`:''}</td><td>${esc(vendorLabel(e.vendorType)||'—')}</td><td class="money-positive">${euro(exhibitorRevenue(e,db.settings))}</td><td>${Number(e.tables)||1}</td><td>${e.zone?coloredTag(zname(e.zone)):sug?`<button class="btn small" data-accept-zone="${esc(e.id)}:${sug.z}">✓ ${coloredTag(zname(sug.z))}</button>`:'Suggestion indisponible'}</td><td>${pill(e.status)}</td><td>${commentPreview('exhibitors',e)}</td><td><button class="linkbtn" data-edit="exhibitors:${esc(e.id)}">Ouvrir →</button></td></tr>`}).join('')}</tbody></table>`:empty('Aucun exposant','Importe un CSV ou crée une fiche.')}</div>`}
function exhibitorPlan(){const plan=db.settings.planPdf,isImage=plan&&/\.(png|jpe?g)$/i.test(plan.fileName||''),pins=(db.settings.planPins||[]).filter(x=>x.blobId===plan?.blobId);return heading('INSCRIPTIONS','Plan des exposants','Plan consultable et annotable pour cette édition.')+`<div class="tabs"><button data-exhibitor-tab="exhibitors">Exposants</button><button data-exhibitor-tab="partners">Partenaires du salon</button><button class="active" data-exhibitor-tab="plan">Plan</button></div><section class="panel exhibitor-plan"><div class="panel-head"><div><h2>Plan du salon · ${editionYear}</h2><p class="sub">${isReadOnly()?'Consulte les repères enregistrés.':'Clique directement sur le plan pour ajouter un pin et son commentaire.'}</p></div>${plan?`<button class="linkbtn" data-blob-download="${esc(plan.blobId)}">Télécharger ↧</button>`:''}</div><div class="plan-actions"><label class="plan-upload">${plan?'Remplacer le plan':'Importer un plan'}<input id="planPdfUpload" type="file" accept="application/pdf,image/png,image/jpeg,.pdf,.png,.jpg,.jpeg"></label>${plan?`<span class="plan-name">${esc(plan.fileName)}</span><button class="btn danger small" data-plan-remove="1">Retirer le plan</button>`:''}</div>${plan?`<div class="plan-tools"><button type="button" class="btn small" data-plan-zoom="out" aria-label="Dézoomer">−</button><span id="planZoomLabel">100 %</span><button type="button" class="btn small" data-plan-zoom="in" aria-label="Zoomer">+</button><button type="button" class="linkbtn" data-plan-zoom="reset">Ajuster à la largeur</button></div><div class="plan-board"><div class="plan-preview-scroll" id="planPreview" data-plan-id="${esc(plan.blobId)}" data-plan-kind="${isImage?'image':'pdf'}"><div class="plan-surface" data-plan-surface="1">${isImage?`<img class="plan-image" data-plan-image-id="${esc(plan.blobId)}" alt="Plan du salon ${editionYear}">`:'<canvas id="planCanvas" aria-label="Aperçu du plan PDF"></canvas>'}${pins.map((pin,i)=>`<button type="button" class="plan-pin" style="left:${Math.max(0,Math.min(100,Number(pin.x)||0))}%;top:${Math.max(0,Math.min(100,Number(pin.y)||0))}%" data-plan-pin="${esc(pin.id)}" title="${esc(pin.comment||'Repère '+(i+1))}" aria-label="Ouvrir le repère ${i+1} : ${esc(pin.comment||'Sans commentaire')}">${i+1}</button>`).join('')}</div><p class="plan-loading" id="planLoading">Chargement du plan…</p></div><aside class="plan-comments" aria-label="Commentaires du plan"><div class="panel-head"><h2>Commentaires</h2><strong>${pins.length}</strong></div><p class="sub">${isReadOnly()?'Sélectionne un repère pour lire son commentaire.':'Clique sur le plan pour ajouter un pin. Clique sur un numéro pour modifier son commentaire.'}</p><div class="plan-pin-list">${pins.length?pins.map((pin,i)=>`<button type="button" class="plan-comment" data-plan-pin="${esc(pin.id)}"><span class="plan-comment-number">${i+1}</span><span>${esc(pin.comment||'Sans commentaire')}</span></button>`).join(''):'<p class="sub">Aucun commentaire sur ce plan.</p>'}</div></aside></div>`:empty('Aucun plan ajouté','Importe un fichier PDF, PNG ou JPG pour afficher le plan de cette édition.')}</section>`}
function editPlanPin(pin){if(isReadOnly()){modal('Repère',`<p>${esc(pin.comment||'Sans commentaire')}</p>`);return}const number=pin.id?(db.settings.planPins||[]).filter(x=>x.blobId===db.settings.planPdf?.blobId).findIndex(x=>x.id===pin.id)+1:(db.settings.planPins||[]).filter(x=>x.blobId===db.settings.planPdf?.blobId).length+1;modal(`Pin n°${number} · ${pin.id?'Modifier':'Ajouter'} un commentaire`,`<form id="planPinForm" data-id="${esc(pin.id||'')}" data-x="${pin.x}" data-y="${pin.y}"><div class="form-grid"><label class="full">Commentaire<textarea name="comment" required>${esc(pin.comment||'')}</textarea></label></div><div class="modal-actions">${pin.id?`<button type="button" class="btn danger" data-plan-pin-remove="${esc(pin.id)}">Supprimer</button>`:''}<button class="btn primary">Enregistrer</button></div></form>`)}
function participationSummary(kind){const totals=participationTotals(db);return `<section class="forecast-cards participation-summary" aria-label="Totaux ${kind==='partners'?'partenaires':'exposants'}">${kind==='exhibitors'?`<div class="stat"><span class="k">Total des tables</span><strong>${totals.tables}</strong></div>`:''}<div class="stat"><span class="k">${kind==='partners'?'Montant total partenaires':'Montant total tables / stands'}</span><strong class="money-positive">${euro(totals[kind])}</strong><small>${kind==='partners'?'Accords, confirmations et partenaires terminés':'Exposants hors annulations'}</small></div></section>`}
function exhibitorPartners(){let rows=filterItems(db.partners,['company','name','zone','community','unit','quantity','status','note']);return heading('INSCRIPTIONS','Partenaires du salon','Zone, surface, tarif et goodies VIP.',actions('partners'))+`<div class="tabs"><button data-exhibitor-tab="exhibitors">Exposants</button><button class="active" data-exhibitor-tab="partners">Partenaires du salon</button><button data-exhibitor-tab="plan">Plan</button></div>`+participationSummary('partners')+searchBar()+`<div class="panel table-wrap">${rows.length?`<table class="data"><thead><tr>${[['company','Partenaire'],['zone','Zone'],['community','Communauté'],['unit','Type'],['quantity','Tables / m²'],['status','Statut'],['goodiesYes','Goodies'],['note','Commentaires']].map(([k,l])=>filterHead(db.partners,k,l)).join('')}<th>Montant</th><th>Action</th></tr></thead><tbody>${rows.map(x=>`<tr tabindex="0" data-row-edit="partners:${esc(x.id)}"><td><strong>${x.logoId?`<img class="table-logo" data-blob-id="${esc(x.logoId)}" alt="${esc(x.company)}">`:esc(x.company||'—')}</strong></td><td>${coloredTag(zname(x.zone))}</td><td>${coloredTag(x.community)}</td><td>${esc(x.unit||'Table')}</td><td>${Number(x.quantity)||0}</td><td>${pill(x.status)}</td><td>${x.goodiesYes===undefined?'—':x.goodiesYes?'Oui':'Non'}</td><td>${commentPreview('partners',x)}</td><td class="money-positive">${euro(partnerAmount(x))}</td><td><button class="linkbtn" data-edit="partners:${esc(x.id)}">Ouvrir →</button></td></tr>`).join('')}</tbody></table>`:empty('Aucun partenaire','Ajoute un partenaire et choisis sa zone.')}</div>`}
const animationColors=['#1303E3','#FE4F14','#00A758','#0C9EAC','#B38B00'];
const cfg={animations:{label:'animation',fields:[['title','Nom de l’animation','text'],['start','Début (8 h à 20 h)','time'],['end','Fin (8 h à 20 h)','time'],['owner','Responsable','owner'],['partnerId','Partenaire','partner-select'],['provider','Prestataire (si absent des partenaires)','text'],['color','Couleur','palette'],['note','Commentaire','textarea']]},ideas:{label:'idée',fields:[['title','Idée','text'],['author','Qui a eu l’idée ?','owner'],['price','Prix estimé (€)','number'],['link','Lien','url'],['note','Commentaire','textarea']]},assets:{label:'asset',fields:[['title','Nom du document','text'],['category','Catégorie','select',['Charte','Insta','Presse','Dédicace','Autre']],['categoryOther','Préciser si Autre','text'],['author','Auteur','owner'],['note','Commentaire','textarea']]},invoices:{label:'facture ou devis',fields:[['title','Nom du document','text'],['tag','Type','select',['Facture','Devis']],['amount','Montant (€)','number'],['partnerId','Partenaire','partner-select'],['sentDate','Date d’envoi','date'],['validated','Validé','check'],['status','Statut','select',['Refusé','Non payé','Payé','Paiement en cours']],['author','Auteur','owner'],['note','Commentaire','textarea']]},partners:{label:'partenaire',fields:[['company','Société','company-select'],['name','Interlocuteur','contact-select'],['email','Email','email'],['phone','Téléphone','tel'],['zone','Zone','zone'],['community','Communauté','select',['Basket','Soccer','Sport US','TCG','Autre']],['unit','Surface facturée','select',['Table','m²']],['tables','Nombre de tables','number'],['area','Surface en m²','number'],['amount','Montant (€)','number'],['amountForced','Montant forcé manuellement','check'],['goodiesYes','Goodies VIP fournis','check'],['status','Statut','select',['À contacter','À relancer','En discussion','Accord','Refusé','Terminé']],['next','Prochaine relance','date'],['invoiceSent','Date d’envoi de facture','date'],['owner','Responsable','owner'],['note','Commentaire interne','textarea']]},contacts:{label:'contact',fields:[['company','Société','text'],['last','Nom','text'],['first','Prénom','text'],['phone','Téléphone','tel'],['email','Email','email'],['role','Rôle','text'],['type','Type','select',['Partenaire','Presse','Bar','Salle','Autre']],['typeOther','Préciser si Autre','text'],['note','Commentaire','textarea']]},tasks:{label:'tâche',fields:[['title','Intitulé','text'],['category','Catégorie','select',['Organisation','Exposants','Partenaires','Communication','Animations','Déco','Logistique','Autre']],['assigneeId','À réaliser par','task-member'],['status','Statut','select',['À faire','En cours','En attente','Terminée']],['start','Début','date'],['due','Échéance','date'],['priority','Priorité','select',['Normale','Haute','Basse']],['link','Lien','url'],['note','Commentaire','textarea']]},posts:{label:'communication',fields:[['title','Sujet','text'],['group','Canal','select',['RS','Presse','Web']],['channel','Sous-canal RS','select',['Instagram','Facebook','Autre']],['company','Entreprise / média','text'],['contact','Contact','contact-select'],['direct','Contact direct','text'],['firstContact','Date du premier contact','date'],['status','Statut','select',['Idée','À faire','À créer','En validation','Planifiée','Terminée','À contacter','À relancer','En cours','C’est mort','Publié']],['date','Date prévue / publication','date'],['owner','Responsable','owner'],['link','Lien','url'],['note','Commentaire','textarea']]},expenses:{label:'élément',fields:[['title','Élément','text'],['category','Catégorie','select',['Décoration','Signalétique','Scène','Mobilier','Communication','Animation','Logistique','Autre']],['quantity','Quantité','number'],['estimated','Prix total prévu (€)','number'],['receivedDate','Date réception','date'],['supplier','Fournisseur','text'],['link','Lien produit / devis','url'],['status','Statut','select',['À designer','À commander','À payer','Commandé','En impression','Reçu','Annulé']],['note','Commentaire','textarea']]}};
function postGroup(x){return x.group||(/Presse/i.test(x.channel)?'Presse':/Site web/i.test(x.channel)?'Web':'RS')}
function channelColor(c){return {'Instagram':'#da4a8b','Facebook':'#3972cb','TikTok':'#16151f','LinkedIn':'#0877b7','Site web':'#6a55bd','Email':'#27a88e','Presse':'#ec862a','Autre':'#777b8c'}[c]||'#777b8c'}
function calendar(kind,cols=[]){let current=calendarDate[kind],year=current.getFullYear(),month=current.getMonth(),mode=calendarMode[kind],first=new Date(year,month,1),offset=(first.getDay()+6)%7,days=new Date(year,month+1,0).getDate(),today=new Date().toISOString().slice(0,10),items=db[kind].filter(x=>(kind!=='posts'||postGroup(x)===commTab)&&JSON.stringify(x).toLowerCase().includes(query.toLowerCase())&&cols.every(([k])=>!columnFilters[k]||String(x[k]??'')===columnFilters[k]));let label=mode==='year'?String(year):first.toLocaleDateString('fr-FR',{month:'long',year:'numeric'});let head=`<div class="calendar-tools"><div class="actions"><button class="btn small" data-cal-nav="${kind}:-1">←</button><button class="btn small" data-cal-today="${kind}">Aujourd’hui</button><button class="btn small" data-cal-nav="${kind}:1">→</button><strong style="text-transform:capitalize;margin-left:8px">${esc(label)}</strong></div><div class="actions">${[['week','Semaine'],['month','Mois'],['year','Année']].map(([k,n])=>`<button class="btn small ${mode===k?'dark':''}" data-cal-mode="${kind}:${k}">${n}</button>`).join('')}</div></div>`;let key=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;let entry=(x,d)=>{if(kind==='posts')return x.date===d;let a=x.start||x.due,b=x.due||x.start;return a&&a<=d&&b>=d};let event=x=>`<button class="calendar-event ${kind==='posts'?'post':''}" style="--event-color:${kind==='posts'?channelColor(x.channel):'#6c55bc'}" data-edit="${kind}:${esc(x.id)}" title="${esc(x.title)} · ${esc(x.channel||x.status||'')}">${esc(x.title)}</button>`;let cells=(m,compact=false)=>{let start=new Date(year,m,1),off=(start.getDay()+6)%7,n=new Date(year,m+1,0).getDate(),count=Math.ceil((off+n)/7)*7;return `<div class="calendar-grid ${compact?'compact':''}">${['L','M','M','J','V','S','D'].map(x=>`<div class="calendar-weekday">${x}</div>`).join('')}${Array.from({length:count},(_,i)=>{let d=new Date(year,m,1-off+i),k=key(d),events=items.filter(x=>entry(x,k));return `<div class="calendar-day ${d.getMonth()!==m?'outside':''} ${k===today?'today':''}"><button class="calendar-date" data-cal-add="${kind}:${k}" title="Ajouter à cette date">${d.getDate()} <span>＋</span></button><div class="calendar-events">${compact?events.length?`<button class="calendar-dot" data-cal-jump="${kind}:${k}" title="${events.length} élément(s)" style="--event-color:${kind==='posts'?channelColor(events[0].channel):'#6c55bc'}">${events.length}</button>`:'':events.map(event).join('')}</div></div>`}).join('')}</div>`};let body;if(mode==='year')body=`<div class="year-grid">${Array.from({length:12},(_,m)=>`<div class="year-month"><h3>${esc(new Date(year,m,1).toLocaleDateString('fr-FR',{month:'long'}))}</h3>${cells(m,true)}</div>`).join('')}</div>`;else if(mode==='month')body=`<div class="calendar-scroll">${cells(month)}</div>`;else{let d=new Date(current);d.setDate(d.getDate()-(d.getDay()+6)%7);body=`<div class="calendar-scroll"><div class="calendar-grid">${['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'].map(x=>`<div class="calendar-weekday">${x}</div>`).join('')}${Array.from({length:7},(_,i)=>{let day=new Date(d);day.setDate(d.getDate()+i);let k=key(day);return `<div class="calendar-day"><button class="calendar-date" data-cal-add="${kind}:${k}">${day.getDate()} <span>＋</span></button><div class="calendar-events">${items.filter(x=>entry(x,k)).map(event).join('')}</div></div>`}).join('')}</div></div>`}return `<div class="panel">${head}${body}<p class="sub" style="margin-top:12px">Clique sur une date pour ajouter un élément. En vue annuelle, clique sur le compteur pour ouvrir la semaine correspondante.</p>${kind==='posts'?`<div class="legend">${[...new Set(items.map(x=>x.channel).filter(Boolean))].map(c=>`<span><i style="background:${channelColor(c)}"></i>${esc(c)}</span>`).join('')}</div>`:''}</div>`}

function generic(kind){let item=db[kind],titles={partners:['RÉSEAU','Partenaires','Contacts et relances des partenaires.'],contacts:['RÉSEAU','Contacts & partenaires','Garde le fil des échanges et des relances.'],tasks:['PRODUCTION','Backlog','Suis les responsabilités et ajuste les dates à tout moment.'],posts:['CONTENUS','Communication','Programme tes publications par canal.'],expenses:['RESSOURCES','Déco & budget','Compare les estimations aux dépenses réelles.']},h=titles[kind];let filtered=item.filter(x=>JSON.stringify(x).toLowerCase().includes(query.toLowerCase()));let cols={partners:[['company','Société'],['name','Contact'],['zone','Zone'],['community','Communauté'],['status','Statut'],['next','Relance'],['owner','Responsable'],['note','Commentaires']],contacts:[['company','Société'],['name','Contact'],['type','Type'],['status','Statut'],['next','Relance'],['owner','Responsable'],['note','Commentaire']],tasks:[['title','Tâche'],['category','Catégorie'],['owner','Responsable'],['due','Échéance'],['status','Statut'],['note','Commentaire']],posts:[['title','Contenu'],['channel','Canal'],['date','Publication'],['owner','Responsable'],['status','Statut'],['note','Commentaire']],expenses:[['title','Élément'],['category','Catégorie'],['quantity','Qté'],['estimated','Prix total'],['supplier','Fournisseur'],['receivedDate','Date réception'],['status','Statut'],['note','Commentaire']]}[kind];filtered=filtered.filter(x=>cols.every(([k])=>!columnFilters[k]||String(x[k]??'')===columnFilters[k]));let table=`<div class="panel table-wrap">${filtered.length?`<table class="data"><thead><tr>${cols.map(([k,label])=>`<th>${label}<select class="column-filter" data-column="${k}" aria-label="Filtrer ${label}"><option value="">Tous</option>${[...new Set(item.map(x=>String(x[k]??'')).filter(Boolean))].sort().map(v=>`<option value="${esc(v)}" ${columnFilters[k]===v?'selected':''}>${esc(k==='vendorType'?vendorLabel(v):v)}</option>`).join('')}</select></th>`).join('')}<th></th></tr></thead><tbody>${filtered.map(x=>`<tr tabindex="0" data-row-edit="${kind}:${esc(x.id)}">${cols.map(([k])=>`<td>${k==='note'&&kind==='partners'?commentPreview(kind,x):k==='status'?pill(x[k])+(kind==='tasks'?completionMarkup(x,esc,cloud.members):''):k==='estimated'||k==='actual'?`<span class="money-negative">${euro(x[k])}</span>`:k==='due'||k==='next'||k==='date'||k==='receivedDate'?date(x[k]):k==='zone'||k==='community'?coloredTag(k==='zone'?zname(x[k]):x[k]):k==='company'&&x.logoId?`<span class="logo-cell"><img data-blob-id="${esc(x.logoId)}" alt="${esc(x[k]||'Logo partenaire')}"></span>`:esc(kind==='tasks'&&k==='owner'?x.assigneeId||x.owner?accountName(x.assigneeId,cloud.members,x.owner):'—':x[k]||'—')}</td>`).join('')}<td><button class="linkbtn" data-edit="${kind}:${esc(x.id)}">Ouvrir →</button></td></tr>`).join('')}</tbody></table>`:empty('Aucune donnée','Ajoute un premier élément pour commencer.')}</div>`;let extra='';if(kind==='expenses')extra=`<div class="cards deco-total" style="grid-template-columns:repeat(2,1fr)"><div class="stat"><span class="k">Total prévu</span><strong><span class="money-negative">${euro(sum(item,x=>x.estimated))}</span></strong></div></div>`;let tabs=['tasks','posts'].includes(kind)?`<div class="tabs">${kind==='tasks'?`<button class="${tab.tasks==='backlog'?'active':''}" data-tab="tasks:backlog">Backlog</button>`:''}${kind==='tasks'?'':`<button class="${tab[kind]==='list'?'active':''}" data-tab="${kind}:list">Liste</button>`}<button class="${tab[kind]==='calendar'?'active':''}" data-tab="${kind}:calendar">Calendrier</button></div>`:'';return heading(h[0],h[1],h[2],actions(kind))+(kind==='partners'?participationSummary('partners'):'')+extra+tabs+(kind==='tasks'&&tab.tasks==='backlog'?searchBar()+backlogMarkup(db.tasks,taskColumns(db.settings,cloud.members),cloud,esc,query,{statuses:backlogStatuses,overdueColor:db.settings.taskOverdueColor}):tab[kind]==='calendar'?searchBar()+filterBar(kind,item,cols)+calendar(kind,cols):(kind==='expenses'?'':`<div class="toolbar"><input class="search" id="search" placeholder="Rechercher…" value="${esc(query)}"></div>`)+table)}

function addressBook(){let items=db.contacts,cols=[['company','Société'],['last','Nom'],['first','Prénom'],['phone','Téléphone'],['email','Email'],['role','Rôle'],['type','Type'],['typeOther','Précision']];let rows=filterItems(items,cols.map(x=>x[0]));return heading('RÉPERTOIRE','Contacts','Carnet de contacts du salon.',`<button class="btn" data-action="import-contacts">↑ Import CSV</button>${actions('contacts')}`)+searchBar()+`<div class="panel table-wrap">${rows.length?`<table class="data"><thead><tr>${cols.map(([k,l])=>filterHead(items,k,l)).join('')}<th>Action</th></tr></thead><tbody>${rows.map(x=>`<tr tabindex="0" data-row-edit="contacts:${esc(x.id)}">${cols.map(([k])=>`<td>${esc(kind==='tasks'&&k==='owner'?x.assigneeId||x.owner?accountName(x.assigneeId,cloud.members,x.owner):'—':x[k]||'—')}</td>`).join('')}<td><button class="linkbtn" data-edit="contacts:${esc(x.id)}">Ouvrir →</button></td></tr>`).join('')}</tbody></table>`:empty('Carnet vide','Crée un contact ou importe un CSV.')}</div>`}
function bilan(){
 const ready=Array.isArray(db.ledger_entries)&&Array.isArray(db.ledger_categories);
 if(!ready)return heading('COMPTABILITÉ','Bilan','Dépenses, ventes et solde du compte NC.')+`<div class="panel"><h2>Le Bilan est prêt à être activé</h2><p>Exécute la migration Supabase 004_bilan.sql puis recharge cette page.</p></div>`;
 const data=bilanData(db),eur=n=>euro(n/100),editable=!isReadOnly();
 const total=(label,value,cl)=>`<div class="stat"><span class="k">${label}</span><strong class="${cl}">${eur(value)}</strong></div>`;
 return heading('COMPTABILITÉ','Bilan','Factures payées, location de salle, billetterie estimée, tables et partenaires engagés sont repris automatiquement. Les autres lignes sont saisies ici.')+`<div class="bilan-totals">${total('Total dépenses',data.expenses,'money-negative')}${total('Total ventes',data.sales,'money-positive')}${total('Résultat · ventes − dépenses',data.delta,moneyClass(data.delta))}${total('Nouveau solde NC',data.balance,moneyClass(data.balance))}</div><div class="panel bilan-account"><form id="ncAccountForm"><label>Compte NC · solde de départ / BFR (€)<input class="field" type="number" step="0.01" name="amount" required value="${data.opening/100}" ${editable?'':'disabled'}></label>${editable?'<button class="btn" type="submit">Enregistrer le solde</button>':''}</form><p class="sub">Le solde de départ ne compte pas comme une vente. Nouveau solde = compte NC + ventes − dépenses.</p></div><div class="bilan-columns">${['expense','sale'].map(side=>`<section class="panel bilan-column ${side}"><div class="panel-head"><h2>${side==='expense'?'Dépenses':'Ventes'}</h2><strong class="${side==='expense'?'money-negative':'money-positive'}">${eur(side==='expense'?data.expenses:data.sales)}</strong></div>${editable?`<div class="actions"><button class="btn primary" data-bilan-add="${side}">+ Ajouter une ligne</button><button class="btn" data-bilan-category="${side}">+ Rubrique</button></div>`:''}${data.categories.filter(c=>c.side===side).map(c=>{const rows=data.rows.filter(x=>x.categoryId===c.id);return `<section class="bilan-category" data-drop-category="${esc(c.id)}"><header><h3>${esc(c.title)}</h3><strong>${eur(rows.reduce((n,x)=>n+x.amountCents,0))}</strong>${editable&&!defaultCategories.some(d=>d.id===c.id)?`<button class="linkbtn" data-category-rename="${esc(c.id)}" aria-label="Renommer la rubrique">✎</button><button class="linkbtn" data-category-delete="${esc(c.id)}" aria-label="Supprimer la rubrique">×</button>`:''}</header>${rows.length?rows.map(row=>`<div class="bilan-row" draggable="${editable}" data-bilan-row="${esc(row.id)}"><span class="drag-handle" aria-hidden="true">⠿</span><div class="bilan-row-body"><strong>${esc(row.title)}</strong>${row.sourceId?`<small>${row.sourceKind==='ticket'?'Billetterie · volume estimé':row.sourceKind==='hall'?'Location · Le Salon':row.sourceKind==='partners-total'?'Total de la page Partenaires · synchronisé':row.sourceKind==='exhibitors-total'?'Total de la page Exposants · synchronisé':row.sourceKind==='partner'?'Partenaire engagé · montant synchronisé':row.sourceKind==='exhibitor'?'Table / stand · montant synchronisé':'Facture payée · montant synchronisé'}</small>`:''}${editable?`<label class="bilan-move">Rubrique<select aria-label="Déplacer ${esc(row.title)} vers une rubrique" data-bilan-move="${esc(row.id)}">${data.categories.filter(v=>v.side===side).map(v=>`<option value="${esc(v.id)}" ${v.id===c.id?'selected':''}>${esc(v.title)}</option>`).join('')}</select></label>`:''}</div><strong class="${side==='expense'?'money-negative':'money-positive'}">${eur(row.amountCents)}</strong><div class="bilan-row-actions">${row.sourceId?`<button class="btn small" ${row.sourceKind==='exhibitors-total'?'data-view="exhibitors"':row.sourceKind==='partners-total'?'data-view="partners"':row.sourceKind==='hall'?'data-view="salon"':row.sourceKind==='ticket'?'data-view="salon"':row.sourceKind==='partner'?`data-edit="partners:${esc(row.sourceId.slice(8))}"`:row.sourceKind==='exhibitor'?`data-edit="exhibitors:${esc(row.sourceId.slice(10))}"`:`data-edit="invoices:${esc(row.sourceId)}"`}>Ouvrir</button>`:editable?`<button class="btn small" data-bilan-edit="${esc(row.id)}">Modifier</button><button class="btn small danger" data-bilan-delete="${esc(row.id)}" aria-label="Supprimer ${esc(row.title)}">×</button>`:''}</div></div>`).join(''):'<p class="sub bilan-drop-hint">Aucune ligne · dépose une ligne ici</p>'}</section>`}).join('')}</section>`).join('')}</div>`;
}
function bilanEditor(side,key){const row=(db.ledger_entries||[]).find(x=>x.id===key),cats=bilanData(db).categories.filter(x=>x.side===side);modal(row?'Modifier la ligne':'Ajouter une '+(side==='sale'?'vente':'dépense'),`<form id="bilanLineForm" data-side="${side}" data-id="${esc(key||'')}"><div class="form-grid"><label class="full">Libellé<input name="title" required value="${esc(row?.title||'')}"></label><label>Montant (€)<input name="amount" type="number" min="0" step="0.01" required value="${row?row.amountCents/100:''}"></label><label>Rubrique<select name="categoryId">${cats.map(c=>`<option value="${esc(c.id)}" ${row?.categoryId===c.id?'selected':''}>${esc(c.title)}</option>`).join('')}</select></label></div><div class="modal-actions"><button class="btn primary">Enregistrer</button></div></form>`)}
function bilanCategoryEditor(side,key){const c=(db.ledger_categories||[]).find(x=>x.id===key);modal(c?'Renommer la rubrique':'Ajouter une rubrique',`<form id="bilanCategoryForm" data-side="${side}" data-id="${esc(key||'')}"><div class="form-grid"><label class="full">Titre<input name="title" required value="${esc(c?.title||'')}"></label></div><div class="modal-actions"><button class="btn primary">Enregistrer</button></div></form>`)}
document.addEventListener('click',e=>{
 const target=e.target.closest('[data-invoice-tab],[data-bilan-add],[data-bilan-edit],[data-bilan-delete],[data-bilan-category],[data-category-rename],[data-category-delete]');if(!target)return;const d=target.dataset;
 if(d.invoiceTab){invoiceTab=d.invoiceTab;query='';columnFilters={};render();return;}
 if(isReadOnly()||!Array.isArray(db.ledger_entries))return;
 if(d.bilanAdd)bilanEditor(d.bilanAdd);
 if(d.bilanEdit){const row=db.ledger_entries.find(x=>x.id===d.bilanEdit);if(row)bilanEditor(row.side,row.id);}
 if(d.bilanCategory)bilanCategoryEditor(d.bilanCategory);
 if(d.categoryRename){const c=db.ledger_categories.find(x=>x.id===d.categoryRename);if(c)bilanCategoryEditor(c.side,c.id);}
 if(d.bilanDelete&&confirm('Supprimer cette ligne du Bilan ?')){db.ledger_entries=db.ledger_entries.filter(x=>x.id!==d.bilanDelete);save();render();}
 if(d.categoryDelete&&confirm('Supprimer cette rubrique ? Ses lignes seront conservées dans la rubrique par défaut.')){const c=db.ledger_categories.find(x=>x.id===d.categoryDelete);if(!c)return;const dest=c.side==='sale'?'sale-other':'expense-other';for(const row of bilanData(db).rows.filter(x=>x.categoryId===c.id))moveBilanRow(db,row.id,dest);db.ledger_categories=db.ledger_categories.filter(x=>x.id!==c.id);save();render();}
});
document.addEventListener('submit',e=>{const form=e.target;if(!['bilanLineForm','bilanCategoryForm','ncAccountForm'].includes(form.id))return;e.preventDefault();if(isReadOnly()||!Array.isArray(db.ledger_entries))return;const f=new FormData(form);
 if(form.id==='ncAccountForm'){db.settings.ncBalance=cents(f.get('amount'))/100;}
 if(form.id==='bilanLineForm'){const title=String(f.get('title')||'').trim(),amount=cents(f.get('amount')),side=form.dataset.side,categoryId=String(f.get('categoryId'));if(!title||amount<0||!bilanData(db).categories.some(c=>c.id===categoryId&&c.side===side))return;const existing=db.ledger_entries.find(x=>x.id===form.dataset.id);const row={id:existing?.id||id(),title,amountCents:amount,side,categoryId,order:existing?.order||Date.now()};if(existing)Object.assign(existing,row);else db.ledger_entries.push(row);}
 if(form.id==='bilanCategoryForm'){const title=String(f.get('title')||'').trim();if(!title)return;const existing=db.ledger_categories.find(x=>x.id===form.dataset.id);if(existing)existing.title=title;else db.ledger_categories.push({id:id(),title,side:form.dataset.side});}
 save();close();render();
});
document.addEventListener('change',e=>{if(e.target.dataset.bilanMove&&!isReadOnly()){if(moveBilanRow(db,e.target.dataset.bilanMove,e.target.value)){save();render();}}});
let draggedBilan=null;
document.addEventListener('dragstart',e=>{const row=e.target.closest('[data-bilan-row]');if(!row||isReadOnly())return;draggedBilan=row.dataset.bilanRow;e.dataTransfer.setData('text/plain',draggedBilan);e.dataTransfer.effectAllowed='move';});
document.addEventListener('dragover',e=>{if(draggedBilan&&e.target.closest('[data-drop-category]')){e.preventDefault();e.dataTransfer.dropEffect='move';}});
document.addEventListener('drop',e=>{const c=e.target.closest('[data-drop-category]');if(!c||!draggedBilan||isReadOnly())return;e.preventDefault();if(moveBilanRow(db,draggedBilan,c.dataset.dropCategory)){save();render();}else notify('Une dépense reste dans les dépenses, une vente dans les ventes.');draggedBilan=null;});
document.addEventListener('dragend',()=>draggedBilan=null);

function animations(){
 const animationDay=salonDate(editionYear,db.settings.salonDate);
 if(!Array.isArray(db.animations))return heading('PROGRAMME','Planning animations','Une journée de 8 h à 20 h.')+'<div class="panel"><h2>Activer le planning</h2><p>Exécute la migration Supabase 005_animations.sql, puis recharge la page.</p></div>';
 const rows=db.animations.filter(x=>x.day===animationDay).sort((a,b)=>String(a.start).localeCompare(String(b.start))),valid=animationLayout(rows),editable=!isReadOnly();
 const lines=Array.from({length:13},(_,i)=>`<div class="animation-hour" style="top:${i*80}px"><span>${String(i+8).padStart(2,'0')}:00</span></div>`).join('');
 const cards=valid.map(x=>{const color=animationColors.includes(x.color)?x.color:animationColors[0];const partner=db.partners.find(p=>p.id===x.partnerId),top=(minutes(x.start)-MINUTE_START)*80/60,height=(minutes(x.end)-minutes(x.start))*80/60;
 return `<button type="button" class="animation-event" style="--animation-color:${color};top:${top}px;height:${Math.max(26,height-4)}px;left:calc(70px + (100% - 78px) * ${x.lane}/${x.columns});width:calc((100% - 78px) / ${x.columns} - 5px)" data-edit="animations:${esc(x.id)}"><strong>${esc(x.start)}–${esc(x.end)} · ${esc(x.title)}</strong><span>${esc([x.owner,partner?.company||partner?.name,x.provider].filter(Boolean).join(' · '))}</span></button>`}).join('');
 const slots=editable?Array.from({length:12},(_,i)=>`<button class="animation-slot" type="button" style="top:${i*80}px;height:80px" data-animation-slot="${String(i+8).padStart(2,'0')}:00" aria-label="Ajouter une animation à ${i+8} h"></button>`).join(''):'';
 return heading('PROGRAMME','Planning animations','Une vue sur la journée, de 8 h à 20 h.',editable?actions('animations'):'')+`<div class="panel animation-panel"><h2>Jour du salon · ${date(animationDay)}</h2><p class="sub">${rows.length} animation${rows.length>1?'s':''} · sélectionne un créneau ou ouvre une animation pour la modifier.</p><div class="animation-scroll"><div class="animation-timeline">${lines}${slots}${cards}</div></div>${db.animations.filter(x=>x.day!==animationDay).length?`<div class="section">Animations enregistrées sur une autre date</div><p class="sub">Ouvre une fiche pour la rattacher au jour du salon.</p>${db.animations.filter(x=>x.day!==animationDay).map(x=>`<button class="btn" data-edit="animations:${esc(x.id)}">${esc(x.title)} · ${date(x.day)}</button>`).join('')}`:''}</div>`;
}
function invoices(){let items=db.invoices.filter(x=>(x.tag||'Facture')===invoiceTab),cols=[['title','Document'],['tag','Type'],['author','Auteur'],['amount','Montant'],['validated','Validé'],['status','Statut'],['note','Commentaire']];let rows=filterItems(items,['title','tag','author','status','note','amount','validated']);return heading('FINANCES','Factures / Devis','Documents, montants et suivi du paiement.',actions('invoices'))+`<div class="tabs">${['Facture','Devis'].map(type=>`<button data-invoice-tab="${type}" class="${invoiceTab===type?'active':''}">${type==='Facture'?'Factures':'Devis'} (${db.invoices.filter(x=>(x.tag||'Facture')===type).length})</button>`).join('')}</div>`+searchBar()+`<div class="panel table-wrap">${rows.length?`<table class="data"><thead><tr><th>Aperçu</th>${cols.map(([k,l])=>filterHead(items,k,l)).join('')}<th>Actions</th></tr></thead><tbody>${rows.map(x=>`<tr tabindex="0" data-row-edit="invoices:${esc(x.id)}"><td><div class="asset-thumb">${x.mime?.startsWith('image/')?`<img data-blob-id="${esc(x.blobId)}" alt="Aperçu">`:'▤'}</div></td><td><strong>${esc(x.title||x.fileName)}</strong></td><td>${pill(x.tag)}</td><td>${esc(x.author||'—')}</td><td class="money-negative">${euro(x.amount)}</td><td>${x.validated?'✓':'—'}</td><td>${pill(x.status)}</td><td>${esc(x.note||'—')}</td><td><div class="actions"><button class="btn small" data-blob-view="${esc(x.blobId)}" ${x.blobId?"":"disabled"}>Voir</button><button class="btn small" data-blob-download="${esc(x.blobId)}" ${x.blobId?"":"disabled"}>↓</button><button class="btn small" data-edit="invoices:${esc(x.id)}">Ouvrir</button></div></td></tr>`).join('')}</tbody></table>`:empty('Aucune facture ou devis','Ajoute un document.')}</div>`}
function communications(){let all=db.posts.filter(x=>postGroup(x)===commTab),active=filterItems(all.filter(x=>x.status!=='Publié'),['title','company','contact','channel','status','owner','note']),published=filterItems(all.filter(x=>x.status==='Publié'),['title','company','channel','owner']);let tabs=`<div class="tabs">${['RS','Presse','Web'].map(k=>`<button class="${commTab===k?'active':''}" data-comm-tab="${k}">${k}</button>`).join('')}</div>`;let controls=`<div class="tabs"><button class="${tab.posts==='list'?'active':''}" data-tab="posts:list">Liste / cartes</button><button class="${tab.posts==='calendar'?'active':''}" data-tab="posts:calendar">Calendrier</button></div>`;let body=tab.posts==='calendar'?calendar('posts',[['group','Canal']]):commTab==='Web'?`<div class="web-board">${[['Idée|À faire','À faire'],['À créer|En cours','En cours'],['En validation','En validation'],['Planifiée|Terminée','Terminé']].map(([status,title])=>`<div class="panel"><h2>${title}</h2>${active.filter(x=>status.split('|').includes(x.status)).map(x=>`<div class="web-card" data-row-edit="posts:${esc(x.id)}"><strong>${esc(x.title)}</strong><small>${esc(x.owner||'—')}</small></div>`).join('')}</div>`).join('')}</div>`:`<div class="panel table-wrap">${postTable(active)}</div>`;return heading('CONTENUS','Communication','RS, presse et web avec historique des publications.',`<button class="btn primary" data-add="posts">+ Ajouter</button>`)+tabs+controls+searchBar()+filterBar('posts',all,[['status','Statut'],['owner','Responsable'],['channel','Sous-canal'],['company','Entreprise']])+body+`<div class="panel"><div class="panel-head"><h2>Publié</h2><small>${published.length} publication(s)</small></div>${published.length?postTable(published,true):empty('Rien de publié','Les éléments au statut Publié apparaîtront ici.')}</div>`}
function postTable(items,pub=false){return items.length?`<table class="data"><thead><tr><th>Sujet</th><th>Canal</th><th>Entreprise</th><th>Contact</th><th>Responsable</th><th>Statut</th><th>${pub?'Publié le':'Date'}</th><th>Action</th></tr></thead><tbody>${items.map(x=>`<tr tabindex="0" data-row-edit="posts:${esc(x.id)}"><td><strong>${esc(x.title)}</strong></td><td>${esc(x.channel||postGroup(x))}</td><td>${esc(x.company||'—')}</td><td>${esc(x.contact||'—')}</td><td>${esc(x.owner||'—')}</td><td>${pill(x.status)}</td><td>${pub?date(x.publishedAt?.slice(0,10)):date(x.date)}</td><td><button class="linkbtn" data-edit="posts:${esc(x.id)}">Ouvrir →</button></td></tr>`).join('')}</tbody></table>`:empty('Aucun élément','Ajoute un contenu ou un contact presse.')}
function backlogSettings(){return `<section class="panel"><h2>Couleur des tâches en retard</h2><label>Couleur d’alerte<input type="color" data-task-overdue-color value="${/^#[0-9a-f]{6}$/i.test(db.settings.taskOverdueColor||'')?db.settings.taskOverdueColor:'#d63d4a'}" ${cloud.role==='admin'&&!cloud.closed?'':'disabled'}></label></section>`;}
function settings(){const logo=db.settings.logoPath?cloud.brandingUrl?.(db.settings.logoPath):editionYear===2026?'/logos/lcs-2026.png':'';return heading('CONFIGURATION','Réglages','Compte, membres et identité visuelle de chaque édition.')+`${cloud.role==='admin'&&cloud.closed?`<section class="panel edition-reopen"><div><span class="eyebrow">ÉDITION ${editionYear}</span><h2>Année clôturée</h2><p class="sub">La réouverture rend à nouveau les fiches modifiables.</p></div><button class="btn primary" data-edition-reopen>Déclôturer ${editionYear}</button></section>`:''}<section class="panel annual-logo-panel"><div><span class="eyebrow">ÉDITION ${editionYear}</span><h2>Logo du salon</h2><p class="sub">Affiché dans le menu et sur les formulaires publics de cette année. PNG, JPG ou WebP · 5 Mo maximum.</p>${logo?`<img class="annual-logo-preview" src="${esc(logo)}" alt="Logo Lille Card Show ${editionYear}">`:'<p class="sub">Aucun logo pour cette édition.</p>'}</div>${!isReadOnly()?`<div class="annual-logo-actions"><label class="btn primary" for="annualLogoUpload">${logo?'Remplacer le logo':'Importer un logo'}</label><input id="annualLogoUpload" type="file" accept="image/png,image/jpeg,image/webp" hidden>${db.settings.logoPath?'<button type="button" class="btn small" data-logo-remove>Retirer le logo</button>':''}<p class="sub" id="annualLogoStatus" role="status"></p></div>`:''}</section><div class="settings-grid"><section class="panel"><div class="panel-head"><h2>Mon compte</h2></div><div id="accountSettings"></div></section><section class="panel"><div class="panel-head"><h2>Membres et responsables</h2></div><div id="membersSettings" role="status">Chargement des membres…</div></section>${backlogSettings()}</div>`}
function salon(){
 const tabs=`<div class="tabs"><button data-salon-tab="information" class="${salonTab==='information'?'active':''}">Informations</button><button data-salon-tab="simulator" class="${salonTab==='simulator'?'active':''}">Simulateur</button></div>`;if(salonTab==='simulator')return heading('ÉDITION '+editionYear,'Le Salon','Simuler le tarif d’un espace et de ses options.')+tabs+spaceSimulator.markup();
 const st=db.settings,tickets=[['general','Entrée grand public','Visiteurs estimés'],['vip','Pack VIP','Packs estimés'],['early','Early Access','Pass estimés']];
 const num=(key,label)=>`<label>${label}<input type="number" min="0" step="0.01" data-salon-number="${key}" value="${esc(st[key]??'')}"></label>`;
 const formatRows=st.tableFormats.map(row=>`<div class="table-format-row ${row.enabled===false?'table-format-disabled':''}"><label>Taille de table<input type="text" data-table-size="${esc(row.id)}" placeholder="Ex. 160 × 60 cm" value="${esc(row.size||'')}"></label><label>Nombre de tables<input type="number" min="0" step="1" data-table-count="${esc(row.id)}" value="${esc(row.quantity??0)}"></label><button type="button" class="btn small table-visibility" data-table-toggle="${esc(row.id)}" aria-label="${row.enabled===false?'Inclure':'Exclure'} ${esc(row.size||'ce format')} du total" aria-pressed="${row.enabled!==false}"><svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M2 12s3.6-6 10-6 10 6 10 6-3.6 6-10 6S2 12 2 12Z"/><circle cx="12" cy="12" r="2.7"/>${row.enabled===false?'<path d="M3 3l18 18"/>':''}</svg></button><button type="button" class="btn small danger" data-table-remove="${esc(row.id)}" aria-label="Supprimer le format ${esc(row.size||'sans taille')}">✕</button></div>`).join('');
 return heading('ÉDITION '+editionYear,'Le Salon','Lieu, capacité, tarifs et fréquentation de cette édition.')+tabs+`<div class="salon-bento">
 <section class="panel salon-intro"><div class="panel-head"><h2>Informations pratiques</h2></div><div class="form-grid"><label class="full">Lieu du salon<input type="text" data-salon-text="venue" placeholder="Nom et adresse du lieu" value="${esc(st.venue||'')}"></label><label class="full">Date du salon<input type="date" data-salon-date value="${salonDate(editionYear,st.salonDate)}" min="${editionYear}-01-01" max="${editionYear}-12-31"></label><label>Prénom du contact<input type="text" data-salon-text="contactFirst" value="${esc(st.contactFirst||'')}"></label><label>Nom du contact<input type="text" data-salon-text="contactLast" value="${esc(st.contactLast||'')}"></label><label>Téléphone du contact<input type="tel" data-salon-text="contactPhone" value="${esc(st.contactPhone||'')}"></label><label>Email du contact<input type="email" data-salon-text="contactEmail" value="${esc(st.contactEmail||'')}"></label><label class="full">Prix de location de la salle (€)<input type="number" min="0" step="0.01" data-salon-number="hallRental" value="${hallRentalAmount(db)}"></label></div></section>
 <section class="panel salon-zones"><div class="panel-head"><h2>Zones du salon</h2><small>Implantation · tables attribuées</small></div><div class="zone-list">${capacityRows()}</div><div class="form-grid salon-zone-inputs"><label class="full">Nombre total de tables<input type="number" min="0" data-total-tables value="${st.totalTables}"></label>${db.zones.map((z,i)=>`<label>${esc(z.name)} · capacité<input type="number" min="0" data-capacity="${i}" value="${z.capacity}"></label>`).join('')}</div><p class="sub salon-note">${sum(db.zones,x=>x.capacity)} tables réparties · écart : ${st.totalTables-sum(db.zones,x=>x.capacity)}.</p></section>
 <section class="panel salon-table-types"><div class="panel-head"><h2>Tables</h2><small>Formats disponibles</small></div><div class="table-format-list">${formatRows||empty('Aucun format','Ajoute les dimensions et le nombre de tables disponibles.')}</div><button type="button" class="btn" data-table-add>+ Ajouter un format</button><p class="sub salon-note">${sum(st.tableFormats.filter(x=>x.enabled!==false),x=>Number(x.quantity)||0)} tables actives · total disponible : ${activeTableTotal()} / ${st.totalTables||0}. Les formats masqués sont déduits du total.</p></section>
 <section class="panel salon-rates"><div class="panel-head"><h2>Tarifs des tables et partenaires</h2></div><div class="salon-rate-groups"><div><h3>Exposants</h3><div class="form-grid">${num('proTablePrice','Table pro (€)')}${num('collectorTablePrice','Table particulier (€)')}${num('artistTablePrice','Table artiste (€)')}${num('exhibitorPartnerPrice','Forfait exposant partenaire (€)')}</div></div><div><h3>Partenaires</h3><div class="form-grid"><label>Prix au m² (€)<input type="number" min="0" step="any" data-partner-price="partnerSqmPrice" value="${st.partnerSqmPrice}"></label><label>Prix par table (€)<input type="number" min="0" step="any" data-partner-price="partnerTablePrice" value="${st.partnerTablePrice}"></label></div></div></div></section>
 <section class="panel salon-ticketing"><div class="panel-head"><h2>Billetterie</h2></div><p class="sub">Les tarifs saisis sont les prix réels des billets. Seuls les volumes sont estimés pour le Prévisionnel.</p><div class="ticket-grid">${tickets.map(([key,label,volume])=>`<div class="ticket-row"><strong>${label}</strong><div class="ticket-fields">${num(key+'Price','Prix du billet (€)')}${num(key+'Quantity',volume)}</div><div class="ticket-result"><span>Recette estimée</span><strong class="money-positive">${euro(Number(st[key+'Price']||0)*Number(st[key+'Quantity']||0))}</strong></div></div>`).join('')}</div></section>
 <section class="panel salon-choices"><div class="panel-head"><h2>Répartition par choix</h2></div><p class="sub">La zone prédite correspond aux choix renseignés par l’utilisateur, dans leur ordre de préférence.</p><div class="form-grid">${st.score.map((v,i)=>`<label>Choix ${i+1} · points<input type="number" min="0" data-score="${i}" value="${v}"></label>`).join('')}</div></section>
 </div>`
}
function ticketRevenue(settings){return ['general','vip','early'].reduce((total,key)=>total+Number(settings[key+'Price']||0)*Number(settings[key+'Quantity']||0),0)}
function revenueLine(x,f){return x.kind==='Table'?Number(x.quantity||0)*Number(f.partnerTablePrice||0):x.kind==='m²'?Number(x.quantity||0)*Number(f.priceSqm||0):Number(x.amount||0)}
function forecast(){let f={...db.forecast2027,hallRental:hallRentalAmount(db)},ticketTotal=ticketRevenue(db.settings),rev=Number(f.proTables)*Number(f.proPrice)+Number(f.collectorTables)*Number(f.collectorPrice)+sum(f.extraRevenue,x=>revenueLine(x,f))+ticketTotal,cost=Number(f.hallRental)+Number(f.deco)+Number(f.social)+Number(f.press)+sum(f.extraExpense,x=>x.amount),remain=Number(f.totalTables)-Number(f.proTables)-Number(f.collectorTables)-Number(f.partnerTables);let input=(k,l)=>`<label>${l}<input type="number" min="0" step="any" data-forecast="${k}" value="${esc(f[k])}"></label>`;let rows=f.extraRevenue.map(x=>`<div class="forecast-line"><input class="field" placeholder="Recette" data-extra-name="extraRevenue:${esc(x.id)}" value="${esc(x.name)}"><select class="field" data-extra-kind="${esc(x.id)}"><option value="Libre" ${!x.kind||x.kind==='Libre'?'selected':''}>Autre</option><option value="Table" ${x.kind==='Table'?'selected':''}>Partenaire · table</option><option value="m²" ${x.kind==='m²'?'selected':''}>Partenaire · m²</option></select><input class="field" type="number" min="0" step="any" aria-label="Montant ou quantité" data-extra-amount="extraRevenue:${esc(x.id)}" value="${esc(x.kind&&x.kind!=='Libre'?x.quantity??0:x.amount??0)}"><strong class="money-positive">${euro(revenueLine(x,f))}</strong><button class="btn small danger" data-extra-delete="extraRevenue:${esc(x.id)}">✕</button></div>`).join('');let out=f.extraExpense.map(x=>`<div class="forecast-extra"><input class="field" data-extra-name="extraExpense:${esc(x.id)}" value="${esc(x.name)}"><input class="field" type="number" min="0" data-extra-amount="extraExpense:${esc(x.id)}" value="${esc(x.amount)}"><button class="btn small danger" data-extra-delete="extraExpense:${esc(x.id)}">✕</button></div>`).join('');return heading('SIMULATION','Prévisionnel','Les partenaires sont facturés par table ou par m² selon chaque ligne de recette.')+`<div class="forecast-cards"><div class="stat"><span class="k">Recettes totales</span><strong class="money-positive">${euro(rev)}</strong></div><div class="stat"><span class="k">Dépenses totales</span><strong class="money-negative">${euro(cost)}</strong></div><div class="stat"><span class="k">Résultat</span><strong class="${moneyClass(rev-cost)}">${signedEuro(rev-cost)}</strong></div></div><div class="panel"><h2>Hypothèses de tables</h2><div class="form-grid">${input('totalTables','Nombre total de tables')}${input('proTables','Tables pro')}${input('collectorTables','Tables particulier')}${input('partnerTables','Tables partenaires')}</div><p class="${remain<0?'warning':'sub'}">${remain}/${f.totalTables} tables restantes</p></div><div class="grid2"><div class="panel"><h2>Recettes</h2><div class="form-grid">${input('proPrice','Prix table pro (€)')}${input('collectorPrice','Prix table particulier (€)')}${input('priceSqm','Prix m² (€)')}${input('partnerTablePrice','Prix de la table partenaire (€)')}</div><p class="sub">Tables pro : ${euro(Number(f.proTables)*Number(f.proPrice))} · Particuliers : ${euro(Number(f.collectorTables)*Number(f.collectorPrice))}</p><div class="section">Billetterie estimée · Le Salon</div><div class="ticket-summary">${[['general','Grand public'],['vip','VIP'],['early','Early Access']].map(([key,label])=>`<div><span>${label} · ${Number(db.settings[key+'Quantity']||0)} × ${euro(Number(db.settings[key+'Price']||0))}</span><strong class="money-positive">${euro(Number(db.settings[key+'Price']||0)*Number(db.settings[key+'Quantity']||0))}</strong></div>`).join('')}<div class="ticket-total"><strong>Total billetterie</strong><strong class="money-positive">${euro(ticketTotal)}</strong></div></div><button class="linkbtn" data-view="salon">Modifier les hypothèses dans Le Salon →</button><div class="section">Recettes supplémentaires</div>${rows}<button class="btn small" data-extra-add="extraRevenue">+ Ajouter une recette</button></div><div class="panel"><h2>Dépenses</h2><div class="form-grid">${input('hallRental','Location salle (€)')}${input('deco','Déco (€)')}${input('social','Com réseaux sociaux (€)')}${input('press','Com presse (€)')}</div><div class="section">Autres dépenses</div>${out}<button class="btn small" data-extra-add="extraExpense">+ Ajouter une dépense</button></div></div>`}
function ideas(){let filtered=filterItems(db.ideas,['title','author','price','link','note']);return heading('INSPIRATION','Boîte à idées','Dépose des pistes, des liens et des visuels, puis retrouve-les facilement.',actions('ideas'))+searchBar()+filterBar('ideas',db.ideas,[['title','Idée'],['author','Auteur'],['price','Prix'],['link','Lien'],['note','Commentaire']])+`<div class="idea-grid">${filtered.length?filtered.map(x=>`<article class="idea-card"><div class="idea-image">${x.imageId?`<img data-blob-id="${esc(x.imageId)}" alt="Visuel de l’idée">`:'✦'}</div><div class="idea-body"><div class="actions" style="justify-content:space-between"><span class="pill">${esc(x.author||'Sans auteur')}</span><span class="idea-price">Montant estimé <strong class="money-negative">${euro(x.price)}</strong></span></div><h2>${esc(x.title||'Sans titre')}</h2><p>${esc(x.note||'Aucun commentaire')}</p>${x.link?`<a href="${safeUrl(x.link)}" target="_blank" rel="noopener noreferrer">Voir le lien ↗</a>`:''}<div class="actions" style="margin-top:15px"><button class="btn small" data-edit="ideas:${esc(x.id)}">Modifier</button><button class="btn small danger" data-delete="ideas:${esc(x.id)}">Supprimer</button></div></div></article>`).join(''):empty('Aucune idée','Ajoute ta première idée.')}</div>`}
const assetCategories=['Tous','Charte','Insta','Presse','Dédicace','Autre'];
function assetCategory(x){let category=String(x.category||'');return assetCategories.includes(category)?category:'Autre'}
function assets(){const items=db.assets.filter(x=>assetTab==='Tous'||assetCategory(x)===assetTab),filtered=filterItems(items,['title','category','categoryOther','author','fileName','note']);return heading('DOCUMENTS','Assets','Tous les documents à consulter et télécharger depuis cet appareil.',actions('assets'))+`<div class="tabs asset-tabs" role="tablist" aria-label="Catégories des assets">${assetCategories.map(category=>`<button type="button" role="tab" aria-selected="${assetTab===category}" data-asset-tab="${esc(category)}" class="${assetTab===category?'active':''}">${esc(category)} <span>${category==='Tous'?db.assets.length:db.assets.filter(x=>assetCategory(x)===category).length}</span></button>`).join('')}</div>`+searchBar()+`<div class="panel table-wrap">${filtered.length?`<table class="data"><thead><tr><th>Aperçu</th><th>Document</th><th>Catégorie</th><th>Auteur</th><th>Fichier</th><th>Commentaire</th><th>Actions</th></tr></thead><tbody>${filtered.map(x=>`<tr tabindex="0" data-row-edit="assets:${esc(x.id)}"><td><div class="asset-thumb">${x.blobId&&x.mime?.startsWith('image/')?`<img data-blob-id="${esc(x.blobId)}" alt="Aperçu">`:'▤'}</div></td><td><strong>${esc(x.title)}</strong></td><td>${esc(x.category==='Autre'?x.categoryOther||'Autre':x.category||'—')}</td><td>${esc(x.author||'—')}</td><td>${esc(x.fileName||'—')}</td><td>${esc(x.note||'—')}</td><td><div class="actions"><button class="btn small" data-blob-view="${esc(x.blobId||'')}">Voir</button><button class="btn small" data-blob-download="${esc(x.blobId||'')}">↓</button><button class="btn small" data-edit="assets:${esc(x.id)}">Modifier</button><button class="btn small danger" data-delete="assets:${esc(x.id)}">✕</button></div></td></tr>`).join('')}</tbody></table>`:empty('Aucun asset','Ajoute un fichier dans cette catégorie.')}</div><div class="note">Les fichiers sont privés et partagés avec les membres autorisés du salon.</div>`}
function syncAssetCategory(){const form=document.querySelector('#editForm[data-kind="assets"]');if(!form)return;const label=form.querySelector('[data-field="categoryOther"]');if(label)label.hidden=form.elements.category.value!=='Autre'}
function syncCommunityWarning(form){if(form?.dataset.kind!=='exhibitors'||form._quoteState?.activeSpaceQuoteId)return;const mismatch=needsCommunityReview({community:form.elements.community.value,choice1:form.elements.choice1.value,communityChoiceApproval:form.dataset.communityApproval});const warning=form.querySelector('#communityEditorWarning');if(warning)warning.hidden=!mismatch;if(mismatch)form.elements.status.value='À contacter'}
function safeUrl(v){try{let u=new URL(v);return ['https:','http:'].includes(u.protocol)?esc(u.href):'#'}catch(e){return '#'}}
function searchBar(){return `<div class="toolbar"><input class="search" id="search" placeholder="Rechercher…" value="${esc(query)}"></div>`}
function filterItems(items,keys){return items.filter(x=>JSON.stringify(keys.map(k=>x[k])).toLowerCase().includes(query.toLowerCase())&&keys.every(k=>!columnFilters[k]||String(x[k]??'')===columnFilters[k]))}
function filterHead(items,k,label){return `<th>${label}<select class="column-filter" data-column="${k}" aria-label="Filtrer ${label}"><option value="">Tous</option>${[...new Set(items.map(x=>String(x[k]??'')).filter(Boolean))].sort().map(v=>`<option value="${esc(v)}" ${columnFilters[k]===v?'selected':''}>${esc(k==='vendorType'?vendorLabel(v):v)}</option>`).join('')}</select></th>`}
