  for(const key of ['order','ticket','first','last','company','email','phone','rate','rawCommunity','sourceStatus','sourceAmount'])if(row[key])ex[key]=row[key];
  ex.name=[ex.first,ex.last].filter(Boolean).join(' ')||ex.name||'';if(row.zone){const zone=resolveZone(row.zone,db.zones);if(zone)ex.zone=zone.id;else invalidZones++;}
  if(isNew||!ex.vendorEdited)ex.vendorType=row.vendorType;
  if(row.tables||isNew)ex.tables=tableCount(row.tables,ex.tables);
  if(isNew||!ex.amountEdited){const total=exhibitorAmount(ex.vendorType,ex.tables,db.settings);if(total!==null)ex.amount=total;ex.amountEdited=false}
