const putBlob=(key,blob)=>cloud.putBlob(key,blob),getBlob=key=>cloud.getBlob(key),deleteBlob=async()=>{};let objectUrls=new Map();async function hydrateBlobs(){for(let el of document.querySelectorAll('img[data-blob-id],img[data-plan-image-id]')){let key=el.dataset.blobId||el.dataset.planImageId;try{if(!objectUrls.has(key)){let b=await getBlob(key);if(b)objectUrls.set(key,URL.createObjectURL(b))}if(el.isConnected){let url=objectUrls.get(key)||'';el.src=url}}catch(e){}}}let planZoom=1,planGeneration=0;
