function taskMove(key,target,beforeId){const t=db.tasks.find(t=>t.id===key),column=boardColumns().find(c=>c.id===target);if(!t||!column)return;try{moveTask(t,column,cloud,cloud.members);backlogStatuses[target]=t.status==='Terminée'?'Terminée':t.status==='En cours'?'En cours':'À faire';const rows=db.tasks.filter(x=>x.id!==key&&taskColumn(x,boardColumns())===target).sort((a,b)=>taskRank(a,db.tasks)-taskRank(b,db.tasks));const at=rows.findIndex(x=>x.id===beforeId);t.rank=at<0?(rows.length?taskRank(rows.at(-1),db.tasks):0)+1024:at===0?taskRank(rows[0],db.tasks)-1024:(taskRank(rows[at-1],db.tasks)+taskRank(rows[at],db.tasks))/2;boardSave();}catch(err){alert(err.message);render();}}
